/* Geïntegreerde procesfuncties; alle bedrijfswijzigingen gaan naar de Python-server. */
let csrfToken='',v5meta=null,v5tab='workorders',v5rows=[],v5offset=0,v5total=0,v5query='',v5detail=null,v5calendar=null,v5period='week',v5group='date',v5refs={},v5HomeSelection=null,v5home=null;
Object.assign(NAMES,{enterprise:'Werkruimte',notifications:'Mijn meldingen',reportsv5:'Rapportages',settingsv5:'Instellingen'});
GROUPS['DAGELIJKS WERK'].splice(1,0,'enterprise','notifications');GROUPS['INZICHT & AUTOMATISERING'].push('reportsv5');GROUPS['INSTELLINGEN'].push('settingsv5');
const oldCanView=canView;
canView=function(p){if(me.role==='company_admin'&&['users','audit','guide','hrcenter','cao','sos','autopilot','ai','demochain','customerportal'].includes(p))return true;if(p==='enterprise'||p==='notifications')return true;if(p==='reportsv5')return v5meta?.permissions.reports?.read||false;if(p==='settingsv5')return ['admin','company_admin'].includes(me.role);return oldCanView(p)};
api=async function(path,method='GET',data){const headers={'Content-Type':'application/json',...(csrfToken?{'X-CSRF-Token':csrfToken}:{})};if(method==='PUT'&&path.startsWith('records/')){const id=Number(path.split('/').at(-1)),row=records.find(x=>x.id===id);if(row?.version)headers['If-Match']=String(row.version)}const r=await fetch('/api/'+path,{method,credentials:'same-origin',headers,body:data===undefined?undefined:JSON.stringify(data)});let value;try{value=await r.json()}catch{throw Error('Ongeldig serverantwoord. Controleer de verbinding.')}if(!r.ok){if(r.status===401&&path!=='login'){token='';loginScreen()}throw Error(value.error||'Opslaan mislukt.')}return value};
login=async function(e){e.preventDefault();try{const result=await api('login','POST',{username:$('username').value,password:$('password').value,code:$('mfaCode')?.value||'',reset_mfa:$('mfaReset')?.checked||false});csrfToken=result.csrf;token='cookie';sessionStorage.removeItem('roefsToken');await boot()}catch(e){$('loginerr').textContent=e.message}};
boot=async function(){try{me=await api('me');csrfToken=me.csrf;token='cookie';[modules,v5meta]=await Promise.all([api('modules'),api('v5/metadata')]);page='start';initRoefsHistory();await openPage('start',true)}catch(e){token='';loginScreen()}};
const v5OldOpen=openPage;
openPage=async function(p,fromHistory=false){if(!['enterprise','notifications','reportsv5','settingsv5'].includes(p)){await v5OldOpen(p,fromHistory);if(page==='start')await v5Start();return}closeMobileMenu();closeModal();if(!canView(p))return toast('Geen toegang tot deze functie.');const serial=++navigationSerial;if(!fromHistory&&p!==page)history.pushState({roefsPage:p},'','#'+p);page=p;shell();$('content').innerHTML='<p class="v5-loading" role="status">Gegevens laden…</p>';try{if(p==='enterprise')await v5Workspace();else if(p==='notifications')await v5Notifications();else if(p==='reportsv5')await v5Reports();else await v5Settings();if(serial!==navigationSerial)return;document.title=NAMES[p]+' | ROEFS ONE';if(tourActive)renderTourBanner()}catch(e){if(serial===navigationSerial)$('content').innerHTML='<p class="v5-error" role="alert">'+esc(e.message)+'</p>'}};
async function v5Start(){try{const [pref,home]=await Promise.all([api('v5/preferences'),api('v5/home')]);if(page!=='start')return;v5home=home;const actions=document.querySelector('.daily-actions');if(v5meta.permissions.customers?.write)actions?.insertAdjacentHTML('beforeend',`<button class="daily-pill" data-roefs-click="v5HomeNew('customers')">Nieuwe klant</button>`);for(const [p,label] of [['enterprise','Nieuwe opdracht / werkruimte'],['notifications','Mijn meldingen'],['reportsv5','Rapportages']])if(canView(p))actions?.insertAdjacentHTML('beforeend',`<button class="daily-pill" data-roefs-click="openPage('${p}')">${esc(label)}</button>`);document.querySelector('.daily-core')?.insertAdjacentHTML('beforeend',`<div class="cards" aria-label="Actuele dagelijkse aandachtspunten">${home.cards.map((card,i)=>`<button class="card" data-roefs-click="v5HomeDrill(${i})"><b>${card.count}</b><p>${esc(card.title)}</p></button>`).join('')}</div>`);if(!pref.tour_completed)document.querySelector('.daily-core')?.insertAdjacentHTML('beforeend','<div class="v5-first-tour"><b>Welkom bij ROEFS ONE</b><p>Loop door de schermen met de rondleiding.</p><button class="btn yellow" data-roefs-click="startTour()">Rondleiding starten</button> <button class="btn light" data-roefs-click="v5SkipTour()">Nu overslaan</button></div>')}catch(e){toast(e.message)}}
async function v5HomeNew(tab){await v5Select(tab);await v5Edit()}
async function v5HomeDrill(index){const card=v5home.cards[index];await v5Select(card.tab);v5HomeSelection=card;if(card.tab==='calendar'){plannerDate=v5home.date;v5period='day'}await v5Workspace()}
async function v5SkipTour(){await api('v5/preferences','PUT',{tour_completed:1});document.querySelector('.v5-first-tour')?.remove()}
const oldTourMove=tourMove,oldStartTour=startTour,oldEndTour=endTour,oldBanner=renderTourBanner;
startTour=async function(){await api('v5/preferences','PUT',{tour_completed:0,tour_step:0});await oldStartTour()};
tourMove=async function(delta){await oldTourMove(delta);await api('v5/preferences','PUT',{tour_step:guideStep})};
endTour=async function(){oldEndTour();document.querySelectorAll('.v5-highlight').forEach(x=>x.classList.remove('v5-highlight'));try{await api('v5/preferences','PUT',{tour_completed:1,tour_step:guideStep})}catch(e){toast('Voortgang kon niet worden opgeslagen: '+e.message)}};
renderTourBanner=function(){oldBanner();document.querySelectorAll('.v5-highlight').forEach(x=>x.classList.remove('v5-highlight'));document.querySelector('.daily-actions,.plan-controls,.headline')?.classList.add('v5-highlight')};
function v5Label(k){return NL[k]||veldnaam(k)}
function v5Value(k,v){if(k.endsWith('_date')||['date','expires_on'].includes(k))return nlDate(v);if(['amount','net_amount','vat_amount'].includes(k))return nlMoney(v);return v??''}
function v5AllowedTabs(){return [['workorders','Werkopdrachten'],...(v5meta.permissions.shifts?.read||me.role==='employee'?[['calendar','Slimme planning']]:[]),['time','Uren & beoordeling'],['files','Bestanden'],...Object.entries(v5meta.modules).filter(([k])=>!['workorders','shifts','hours','documents'].includes(k)).map(([k,v])=>[k,v.label]),...Object.entries(v5meta.resources).map(([k,v])=>[k,v.label])]}
async function v5Select(tab){v5tab=tab;v5offset=0;v5query='';v5detail=null;v5HomeSelection=null;await openPage('enterprise')}
async function v5Workspace(){const tabs=v5AllowedTabs();if(!tabs.some(x=>x[0]===v5tab))v5tab='workorders';let body=head('Werkruimte','Van klant en opdracht tot uitvoering en factuurvoorbereiding.')+`<div class="v5-tabs" role="group" aria-label="Onderdelen werkruimte">${tabs.map(([k,name])=>`<button class="btn ${k===v5tab?'yellow':'light'}" data-roefs-click="v5Select('${k}')">${esc(name)}</button>`).join('')}</div><div id="v5body"></div>`;$('content').innerHTML=body;
 if(v5tab==='calendar')return v5Calendar();if(v5tab==='files')return v5Files();if(v5tab==='time')return v5Time();
 const isResource=!!v5meta.resources[v5tab];let result=await api(v5tab==='workorders'?'v5/workorders':isResource?'v5/resources/'+v5tab:'v5/entities/'+v5tab+'?limit=25&offset='+v5offset+'&q='+encodeURIComponent(v5query)+(v5HomeSelection&&v5HomeSelection.tab===v5tab?'&ids='+encodeURIComponent(v5HomeSelection.ids.join(',')||'0'):''));v5rows=Array.isArray(result)?result:result.items;if(Array.isArray(result)&&v5HomeSelection?.tab===v5tab)v5rows=v5rows.filter(x=>v5HomeSelection.ids.includes(x.id));v5total=result.total??v5rows.length;
 const meta=v5meta.resources[v5tab]||v5meta.modules[v5tab];const write=meta?.write;let fields=meta?.fields||['description','date','workflow'];
 $('v5body').innerHTML=`<div class="v5-toolbar"><label>Zoeken<input id="v5search" value="${esc(v5query)}" data-roefs-keydown="if(event.key==='Enter')v5Search()"></label><button class="btn light" data-roefs-click="v5Search()">Zoeken</button>${write?'<button class="btn yellow" data-roefs-click="v5Edit()">Nieuw toevoegen</button>':''}<button class="btn light" data-roefs-click="v5DownloadList()">CSV exporteren</button>${v5tab==='customers'?'<button class="btn light" data-roefs-click="v5Import()">Klanten importeren</button>':''}</div><p class="v5-muted">${v5total} opgeslagen records</p><div class="v5-grid">${v5rows.filter(r=>!Array.isArray(result)||JSON.stringify(r).toLowerCase().includes(v5query.toLowerCase())).map(r=>`<article class="v5-item"><h3>${esc(r.name||r.description||r.number||r.plate||'#'+r.id)}</h3><p>${fields.slice(0,6).map(k=>esc(v5Label(k))+': '+esc(v5Value(k,r[k]))).join('<br>')}</p>${v5tab==='workorders'?`<p><b>${esc(r.workflow||r.status)}</b></p><button class="btn yellow" data-roefs-click="v5Work(${r.id})">Opdracht openen</button>`:''}${write?`<button class="btn light" data-roefs-click="v5Edit(${r.id})">Bewerken</button>`:''}${v5tab==='contracts'?`<button class="btn light" data-roefs-click="v6Contract(${r.id})">Contractdossier</button>`:''}${v5tab==='customers'?`<button class="btn light" data-roefs-click="v5Timeline(${r.id})">Klantdossier</button>`:''}${v5tab==='invoices'&&r.workorder_id?`<button class="btn" data-roefs-click="v5Invoice(${r.id})">Factuurdetails</button>`:''}</article>`).join('')||'<p>Geen gegevens gevonden.</p>'}</div>${!Array.isArray(result)?`<div class="actions"><button class="btn light" ${v5offset===0?'disabled':''} data-roefs-click="v5offset-=25;v5Workspace()">Vorige</button><span>${v5offset+1}–${Math.min(v5offset+25,v5total)}</span><button class="btn light" ${v5offset+25>=v5total?'disabled':''} data-roefs-click="v5offset+=25;v5Workspace()">Volgende</button></div>`:''}`;
}
async function v5Search(){v5query=$('v5search').value;v5offset=0;await v5Workspace()}
const REF={customer_id:'customers',object_id:'objects',employee_id:'employees',manager_id:'employees',team_id:'teams',from_object:'objects',to_object:'objects',workorder_id:'workorders',contract_id:'contracts',required_assets:'assets'};
async function v5References(fields){for(const field of fields){const table=REF[field];if(!table)continue;if(table==='workorders'){v5refs[table]=await api('v5/workorders');continue}if(table==='teams'){if(v5meta.resources.teams)v5refs[table]=await api('v5/resources/teams');continue}if(!v5meta.modules[table])continue;let all=[],offset=0;while(true){const result=await api('v5/entities/'+table+'?limit=100&offset='+offset);all.push(...result.items);offset+=100;if(offset>=result.total)break}v5refs[table]=all}}
function v5Input(k,value='',required=false,options=null){const id='v5-'+k;let input;const ref=REF[k];if(options)input=`<select id="${id}" name="${k}">${options.map(x=>`<option ${String(value)===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`;else if(ref&&v5refs[ref])input=`<select id="${id}" name="${k}" ${required?'required':''} ${k==='required_assets'?'multiple':''}><option value="">Niet gekoppeld</option>${v5refs[ref].map(r=>`<option value="${r.id}" ${(k==='required_assets'?String(value).split(',').includes(String(r.id)):String(value)===String(r.id))?'selected':''}>${esc(r.name||r.description||'#'+r.id)} (#${r.id})</option>`).join('')}</select>`;else if(['description','notes','completion_notes','billing_address','planner_notes','reason'].includes(k))input=`<textarea id="${id}" name="${k}" maxlength="2000" ${required?'required':''}>${esc(value)}</textarea>`;else{const type=k.endsWith('_date')||['date','expires_on','retention_until'].includes(k)?'date':k.endsWith('_time')?'time':k==='email'?'email':['capacity','minutes','break_minutes','emergency_available','hourly_rate'].includes(k)?'number':'text';input=`<input id="${id}" name="${k}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="2000">`}return `<div class="field"><label for="${id}">${esc(v5Label(k))}${required?' *':''}</label>${input}</div>`}
function v5Form(title,fields,row,submit,required=[],statuses=[]){showModal(title,`<form data-roefs-submit="${submit}"><div class="formgrid">${fields.map(k=>v5Input(k,row[k]??'',required.includes(k),k==='status'&&statuses.length?statuses:k==='priority'?['Laag','Normaal','Hoog','Spoed']:null)).join('')}</div><p id="v5error" role="alert" class="v5-error"></p><div class="actions"><button type="button" class="btn light" data-roefs-click="closeModal()">Annuleren</button><button type="submit" class="btn yellow">Opslaan</button></div></form>`)}
function v5FormData(form){const data=Object.fromEntries(new FormData(form));if(form.elements.required_assets)data.required_assets=[...form.elements.required_assets.selectedOptions].map(x=>x.value).filter(Boolean).join(',');return data}
async function v5Submit(e,action){e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await action(v5FormData(e.target));closeModal();toast('Gegevens opgeslagen');if(page==='settingsv5')await v5Settings();else await v5Workspace();return true}catch(error){if($('v5error'))$('v5error').textContent=error.message;else toast(error.message);button.disabled=false;return false}}
async function v5Edit(id){try{const row=id?v5rows.find(r=>r.id===id):{date:localDate(),hours:'0',capacity:1,start_time:'08:00',end_time:'12:00',contract_hours:32};const meta=v5meta.resources[v5tab]||v5meta.modules[v5tab];let fields=meta.fields;if(v5tab==='workorders')fields=['contract_id','object_id','description','date','start_time','end_time','priority','service','team_id','required_skills','required_certifications','required_assets','capacity'];if(v5tab==='invoices')return toast('Gebruik Factuur voorbereiden bij een factureerbare werkopdracht.');await v5References(fields);v5Form((id?'Bewerken':'Toevoegen')+' · '+meta.label,fields,row,`v5SaveEntity(event,${id||0},${row.version||0})`,meta.required||[],meta.statuses||[])}catch(e){toast(e.message)}}
async function v5SaveEntity(e,id,version){await v5Submit(e,async data=>{const base=v5tab==='workorders'?'workorders':v5meta.resources[v5tab]?'resources/'+v5tab:'entities/'+v5tab;await api('v5/'+base+(id?'/'+id:''),id?'PUT':'POST',{...data,...(id?{version}:{})})})}
async function v5Timeline(id){try{const r=await api('v5/customers/'+id+'/timeline');showModal('Klantdossier · '+r.customer.name,['locations','contacts','contracts','workorders','communications','audit'].map((k,i)=>`<h3>${['Locaties','Contactpersonen','Contracten','Werkopdrachten','Contacthistorie','Wijzigingen'][i]}</h3>${r[k].map(x=>`<p>${esc(x.name||x.description||x.subject||x.at+' '+cellText('action',x.action))}</p>`).join('')||'<p>Nog geen gegevens.</p>'}`).join('')+'<button class="btn" data-roefs-click="closeModal()">Sluiten</button>')}catch(e){toast(e.message)}}
async function v5DownloadList(){const fields=(v5meta.resources[v5tab]||v5meta.modules[v5tab]).fields;const csv=[[...fields.map(v5Label)],...v5rows.map(r=>fields.map(f=>v5Value(f,r[f])))].map(r=>r.map(csvCell).join(';')).join('\r\n');v5Blob(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'roefs-'+v5tab+'-huidige-selectie.csv')}
function v5Blob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function v5Download(path,name){try{const r=await fetch('/api/v5/'+path,{credentials:'same-origin'});if(!r.ok){const err=await r.json();throw Error(err.error)}v5Blob(await r.blob(),name)}catch(e){toast(e.message)}}
function v5Import(){showModal('Klanten importeren',`<p>UTF-8 JSON-bestand met een lijst klantrecords. Maximaal 200 per batch. Velden: name, contact, email, phone, city, status. De hele batch wordt gecontroleerd vóór opslag.</p><form data-roefs-submit="v5ImportSave(event)"><input id="v5import" type="file" accept="application/json" required><p id="v5error" class="v5-error" role="alert"></p><button type="submit" class="btn">Importeren</button></form>`)}
async function v5ImportSave(e){await v5Submit(e,async()=>{const file=$('v5import').files[0];if(file.size>600000)throw Error('Importbestand te groot.');await api('v5/customers/import','POST',{rows:JSON.parse(await file.text())})})}
async function v5Work(id){try{v5detail=await api('v5/workorders/'+id);const w=v5detail.workorder;const state=w.workflow||'Concept';const transitions={Concept:['Gepland','Geannuleerd'],Gepland:['Toegewezen','Concept','Geannuleerd'],Toegewezen:['In uitvoering','Gepland','Geannuleerd'],'In uitvoering':['Voltooid','Geannuleerd'],Voltooid:['Goedgekeurd','Correctie'],Correctie:['In uitvoering','Geannuleerd'],Goedgekeurd:['Factureerbaar','Correctie'],Factureerbaar:['Correctie'],Geannuleerd:['Concept']};const states=(transitions[state]||[]).filter(s=>me.role!=='employee'||['In uitvoering','Voltooid'].includes(s));showModal('Werkopdracht #'+id,`<h3>${esc(w.description)}</h3><p>${esc(nlDate(w.date))} · ${esc(w.start_time)}–${esc(w.end_time)}</p><div class="v5-steps">${['Concept','Gepland','Toegewezen','In uitvoering','Voltooid','Goedgekeurd','Factureerbaar'].map(s=>`<span class="${state===s?'current':''}">${s}</span>`).join('')}</div><p><b>Huidige status: ${esc(state)}</b></p><p>${esc(w.completion_notes)}</p><h3>Checklist</h3>${v5detail.checklist.map(t=>`<label><input type="checkbox" ${t.done?'checked':''} data-roefs-change="v5Check(${id},${t.id},${t.version},this.checked)"> ${esc(t.title)}</label>`).join('')||'<p>Nog geen taken vastgelegd.</p>'}${v5meta.permissions.workorders?.write?`<form data-roefs-submit="v5AddCheck(event,${id})"><label>Nieuwe taak<input name="title" required maxlength="300"></label><button class="btn light">Taak toevoegen</button></form>`:''}<h3>Geplande medewerkers</h3>${v5detail.shifts.map(s=>`<p>Medewerker #${s.employee_id} · ${esc(s.start_time)}–${esc(s.end_time)} · ${esc(s.status)}</p>`).join('')||'<p>Nog geen team ingepland.</p>'}<div class="actions">${v5meta.permissions.shifts?.write?`<button class="btn yellow" data-roefs-click="v5Assign(${id})">Medewerkers voorstellen</button>`:''}<button class="btn light" data-roefs-click="v5Download('workorders/${id}/pdf','werkbon-${id}.pdf')">Werkbon PDF</button><button class="btn light" data-roefs-click="v5Upload(${id})">Foto of bestand toevoegen</button><button class="btn light" data-roefs-click="v5TimeForm(${id})">Uren registreren</button><button class="btn light" data-roefs-click="v6ClockForm(${id})">Inklokken</button>${state==='Factureerbaar'&&v5meta.permissions.invoices?.write?`<button class="btn yellow" data-roefs-click="v5Prepare(${id},${w.version})">Factuur voorbereiden</button>`:''}</div><h3>Status wijzigen</h3>${states.map(s=>`<button class="btn light" data-roefs-click="v5TransitionForm(${id},${w.version},'${s}')">${esc(s)}</button>`).join('')}<h3>Statusgeschiedenis</h3><div class="v5-history">${v5detail.events.map(x=>`<p>${esc(x.at)} · ${esc(x.old_state)} → ${esc(x.new_state)}<br>${esc(x.reason)}</p>`).join('')||'<p>Nog geen statuswijzigingen.</p>'}</div><p id="v5error" class="v5-error" role="alert"></p><div class="actions"><button class="btn" data-roefs-click="closeModal()">Sluiten</button></div>`)}catch(e){toast(e.message)}}
async function v5Check(wid,id,version,done){try{await api('v5/workorders/'+wid+'/checklist','POST',{id,version,done});await v5Work(wid)}catch(e){toast(e.message);await v5Work(wid)}}
async function v5AddCheck(e,wid){e.preventDefault();try{await api('v5/workorders/'+wid+'/checklist','POST',{title:e.target.elements.title.value});await v5Work(wid)}catch(e){$('v5error').textContent=e.message}}
function v5TransitionForm(id,version,state){const w=v5detail.workorder;v5Form('Status wijzigen naar '+state,state==='Voltooid'?['completion_notes','signed_by']:['reason'],w,`v5TransitionSave(event,${id},${version},'${state}')`,state==='Voltooid'?['completion_notes']:['Correctie','Geannuleerd'].includes(state)?['reason']:[])}
async function v5TransitionSave(e,id,version,state){e.preventDefault();try{await api('v5/workorders/'+id+'/transition','POST',{...v5FormData(e.target),state,version});await v5Work(id)}catch(e){$('v5error').textContent=e.message}}
async function v5Assign(id){try{const w=(await api('v5/workorders/'+id)).workorder;const r=await api('v5/planning/suggest','POST',{object_id:w.object_id,date:w.date,start_time:w.start_time,end_time:w.end_time,workorder_id:id});v5detail={workorder:w};showModal('Medewerkerssuggesties',`<p>${esc(r.travel)}</p><p>Benodigde medewerkers: ${w.capacity}. Bevestig iedere toewijzing. Verplichte controles kunnen niet worden overgeslagen.</p>${r.candidates.map(x=>`<article class="v5-item"><h3>${esc(x.name)} · score ${x.score}</h3><ul>${x.reasons.map(s=>'<li>'+esc(s)+'</li>').join('')}</ul><button class="btn yellow" data-roefs-click="v5AssignSave(${id},${x.id})">Inplannen</button></article>`).join('')||'<p>Geen geschikte medewerkers gevonden.</p>'}<h3>Niet geschikt</h3>${r.excluded.map(x=>`<p><b>${esc(x.name)}</b>: ${esc(x.reasons.join(' '))}</p>`).join('')}<p id="v5error" class="v5-error" role="alert"></p><button class="btn light" data-roefs-click="v5Work(${id})">Terug naar opdracht</button>`)}catch(e){toast(e.message)}}
async function v5AssignSave(id,eid){const w=v5detail.workorder;try{await api('v5/shifts','POST',{workorder_id:id,object_id:w.object_id,employee_id:String(eid),date:w.date,start_time:w.start_time,end_time:w.end_time,status:'Gepland'});toast('Medewerker ingepland');await v5Assign(id)}catch(e){$('v5error').textContent=e.message}}
function v5OffsetDate(value){const d=new Date(value||Date.now());const mins=-d.getTimezoneOffset();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')+':00'+(mins<0?'-':'+')+String(Math.floor(Math.abs(mins)/60)).padStart(2,'0')+':'+String(Math.abs(mins)%60).padStart(2,'0')}
async function v5Time(){v5rows=await api('v5/hours');if(v5HomeSelection?.tab==='time')v5rows=v5rows.filter(x=>v5HomeSelection.ids.includes(x.id));$('v5body').innerHTML=`<h2>Urenregistratie en beoordeling</h2><p>Gebruik datum, tijd en UTC-offset voor Europe/Amsterdam. Zo blijft nachtwerk en de klokverzetting eenduidig.</p><button class="btn yellow" data-roefs-click="v5TimeForm()">Uren registreren</button><div class="v5-grid">${v5rows.map(r=>`<article class="v5-item"><h3>${esc(nlDate(r.date))} · ${esc(r.hours)} uur</h3><p>Medewerker #${esc(r.employee_id)} · Opdracht #${esc(r.workorder_id||'niet gekoppeld')}<br>${esc(r.status)}<br>${esc(r.reason)}</p>${r.workorder_id?`<button class="btn light" data-roefs-click="v5TimeForm(${r.workorder_id},${r.id})">Corrigeren</button>`:''}${['admin','company_admin','operations','supervisor'].includes(me.role)&&r.status==='Ingediend'?`<button class="btn yellow" data-roefs-click="v5ReviewHours(${r.id},${r.version},'Goedgekeurd')">Goedkeuren</button><button class="btn light" data-roefs-click="v5ReviewHours(${r.id},${r.version},'Afgewezen')">Afwijzen</button>`:''}</article>`).join('')}</div>`}
async function v5TimeForm(wid,id){try{await v5References(['employee_id','workorder_id']);const row=id?v5rows.find(r=>r.id===id):{workorder_id:wid||'',employee_id:me.employee_id||'',starts_at:v5OffsetDate(),ends_at:v5OffsetDate(Date.now()+3600000),break_minutes:0};if(me.role==='employee')v5refs.employees=[{id:me.employee_id,name:me.username}];v5Form('Uren registreren · Europe/Amsterdam',['employee_id','workorder_id','starts_at','ends_at','break_minutes','reason'],row,`v5TimeSave(event,${id||0},${row.version||0})`,['employee_id','workorder_id','starts_at','ends_at','break_minutes']);$('v5-starts_at').insertAdjacentHTML('afterend','<small>Bijvoorbeeld 2026-10-25T02:30:00+02:00 (zomertijd) of +01:00 (wintertijd). Controleer de tijdzone van je toestel.</small>')}catch(e){toast(e.message)}}
async function v5TimeSave(e,id,version){await v5Submit(e,async data=>{await api('v5/hours'+(id?'/'+id:''),id?'PUT':'POST',{...data,...(id?{version}:{})});v5tab='time'})}
function v5ReviewHours(id,version,status){v5Form(status+' · uren',['reason'],{},`v5ReviewHoursSave(event,${id},${version},'${status}')`,status==='Afgewezen'?['reason']:[])}
async function v5ReviewHoursSave(e,id,version,status){await v5Submit(e,data=>api('v5/hours/'+id+'/review','POST',{...data,version,status}))}
function v5Prepare(id,version){v5Form('Conceptfactuur voorbereiden',['hourly_rate','vat_rate','material_description','material_quantity','material_rate','equipment_description','equipment_quantity','equipment_rate'],{hourly_rate:'35.00',vat_rate:'21'},`v5PrepareSave(event,${id},${version})`,['hourly_rate','vat_rate']);$('v5-vat_rate').insertAdjacentHTML('afterend','<small>Btw: 0, 9 of 21. Controleer de fiscale behandeling. Deze tarieven zijn demonstratie-invoer.</small>')}
async function v5PrepareSave(e,id,version){e.preventDefault();try{const data=v5FormData(e.target),lines=[];for(const type of ['material','equipment'])if(data[type+'_description'])lines.push({description:data[type+'_description'],quantity:data[type+'_quantity'],rate:data[type+'_rate'],vat_rate:data.vat_rate});const inv=await api('v5/invoices/prepare','POST',{hourly_rate:data.hourly_rate,vat_rate:data.vat_rate,lines,workorder_id:id,version});await v5Invoice(inv.id)}catch(e){$('v5error').textContent=e.message}}
async function v5Invoice(id){try{const r=await api('v5/invoices/'+id+'/lines');showModal('Conceptfactuur '+r.invoice.number,`<p>${esc(r.invoice.review_status)} · Totaal ${esc(nlMoney(r.invoice.amount))}</p>${r.lines.map(x=>`<p>${esc(x.description)}<br>${esc(x.quantity)} × ${esc(nlMoney(x.rate))} · btw ${esc(x.vat_rate)}% · netto ${esc(nlMoney(x.net))}</p>`).join('')}<div class="actions"><button class="btn" data-roefs-click="v5Download('invoices/${id}/pdf','factuur-${id}.pdf')">PDF downloaden</button><button class="btn light" data-roefs-click="v5Download('invoices/${id}/csv','factuur-${id}.csv')">Boekhoudexport CSV</button>${v5meta.permissions.invoices?.write?`<button class="btn yellow" data-roefs-click="v5InvoiceAction(${id},${r.invoice.version},'review')">Goedkeuren</button><button class="btn light" data-roefs-click="v5InvoiceAction(${id},${r.invoice.version},'credit')">Creditcorrectie</button>`:''}</div><p>Er wordt niets automatisch verzonden of betaald.</p><button class="btn light" data-roefs-click="closeModal()">Sluiten</button>`)}catch(e){toast(e.message)}}
function v5InvoiceAction(id,version,action){v5Form(action==='credit'?'Creditcorrectie':'Factuur goedkeuren',['reason'],{},`v5InvoiceActionSave(event,${id},${version},'${action}')`,action==='credit'?['reason']:[])}
async function v5InvoiceActionSave(e,id,version,action){e.preventDefault();try{const r=await api('v5/invoices/'+id+'/'+action,'POST',{...v5FormData(e.target),version,status:'Goedgekeurd'});await v5Invoice(r.id)}catch(e){$('v5error').textContent=e.message}}
async function v5Files(){v5rows=await api('v5/files');$('v5body').innerHTML=`<h2>Bestanden</h2><p>Private opslag. PNG, JPG, PDF en UTF-8-tekst tot 600 kB. Downloads worden op de server geautoriseerd.</p><button class="btn yellow" data-roefs-click="v5Upload()">Bestand uploaden</button><div class="v5-grid">${v5rows.map(r=>`<article class="v5-item"><h3>${esc(r.name)}</h3><p>${esc(r.category)} · ${Math.ceil(r.size/1024)} kB</p><button class="btn light" data-roefs-click="v5Download('files/${r.id}',${esc(JSON.stringify(r.name))})">Downloaden</button></article>`).join('')||'<p>Geen bestanden gevonden.</p>'}</div>`}
async function v5Upload(wid){try{await v5References(['customer_id','employee_id','workorder_id']);if(me.role==='employee')v5refs.employees=[{id:me.employee_id,name:me.username}];v5Form('Foto of document toevoegen',['category','customer_id','employee_id','workorder_id','retention_until'],{category:'Werkbon',workorder_id:wid||''},'v5UploadSave(event)',['category']);document.querySelector('#modalbg .formgrid').insertAdjacentHTML('afterbegin','<label>Bestand<input id="v5file" class="v5-file" type="file" accept=".png,.jpg,.jpeg,.pdf,.txt" required></label>')}catch(e){toast(e.message)}}
async function v5UploadSave(e){await v5Submit(e,async data=>{const file=$('v5file').files[0];const limits=await api('v5/files/config');if(file.size>limits.max_bytes)throw Error('Bestand overschrijdt de ingestelde limiet van '+limits.max_bytes+' bytes.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=4096)binary+=String.fromCharCode(...bytes.subarray(i,i+4096));await api('v5/files','POST',{...data,name:file.name,content:btoa(binary)});v5tab='files'})}
function v5DayAdd(date,days){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
async function v5Calendar(){try{let start=plannerDate,end=start;const day=new Date(start+'T12:00:00');if(v5period==='week'){start=v5DayAdd(start,-((day.getDay()+6)%7));end=v5DayAdd(start,6)}else if(v5period==='month'){start=start.slice(0,7)+'-01';const last=new Date(day.getFullYear(),day.getMonth()+1,0);end=start.slice(0,7)+'-'+String(last.getDate()).padStart(2,'0')}
 const department=$('v5dept')?.value||'',employee=$('v5employee')?.value||'',customer=$('v5customer')?.value||'';v5calendar=await api('v5/planning/calendar?from='+start+'&to='+end+'&department='+encodeURIComponent(department)+'&employee_id='+encodeURIComponent(employee)+'&customer_id='+encodeURIComponent(customer));const shifts=v5calendar.shifts;let groups=[];
 if(v5group==='date'){for(let date=start;date<=end;date=v5DayAdd(date,1))groups.push([date,nlDate(date),shifts.filter(s=>s.date===date)])}else{const key={employee:'employee_id',team:'team_id',customer:'customer_id',location:'object_id',equipment:'workorder_id'}[v5group];if(v5group==='equipment'){groups=[...new Set(v5calendar.reservations.map(r=>r.asset_id))].map(a=>[String(a),'Materieel #'+a,shifts.filter(s=>v5calendar.reservations.some(r=>r.asset_id===a&&r.workorder_id===s.workorder_id))])}else groups=[...new Set(shifts.map(s=>String(s[key]||'')))].map(g=>[g,(v5group==='employee'?shifts.find(s=>String(s[key])===g)?.employee_name:v5group==='location'?shifts.find(s=>String(s[key])===g)?.object_name:'')||'#'+g,shifts.filter(s=>String(s[key]||'')===g)])}
 $('v5body').innerHTML=`<h2>Slimme planning</h2><div class="v5-toolbar"><label>Datum<input type="date" value="${plannerDate}" data-roefs-change="plannerDate=this.value;v5Calendar()"></label><label>Periode<select data-roefs-change="v5period=this.value;v5Calendar()">${[['day','Dag'],['week','Week'],['month','Maand']].map(([k,n])=>`<option value="${k}" ${v5period===k?'selected':''}>${n}</option>`).join('')}</select></label><label>Groeperen<select data-roefs-change="v5group=this.value;v5Calendar()">${[['date','Datum'],['employee','Medewerker'],['team','Team'],['customer','Klant'],['location','Locatie'],['equipment','Materieel']].map(([k,n])=>`<option value="${k}" ${v5group===k?'selected':''}>${n}</option>`).join('')}</select></label><label>Afdeling<input id="v5dept" value="${esc(department)}"></label><label>Medewerkernummer<input id="v5employee" value="${esc(employee)}" type="number"></label><label>Klantnummer (intern)<input id="v5customer" value="${esc(customer)}" type="number"></label><button class="btn light" data-roefs-click="v5Calendar()">Filteren</button>${v5meta.permissions.shifts?.write?'<button class="btn yellow" data-roefs-click="v5ShiftForm()">Dienst toevoegen</button><button class="btn light" data-roefs-click="v6Series()">Meerdaags en herhalen</button>':''}</div><p>Sleep een dienst naar een datum of medewerker. Op mobiel en met toetsenbord: open de dienst en kies Bewerken. Iedere wijziging wordt op de server opnieuw gecontroleerd.</p><div class="v5-calendar" tabindex="0" aria-label="Planning; horizontaal verschuifbaar">${groups.map(([key,label,rows])=>`<section class="v5-day" data-roefs-dragover="event.preventDefault()" data-roefs-drop="v5Drop(event,'${esc(key)}')"><h3>${esc(label)}</h3>${rows.map(s=>`<button class="v5-shift" draggable="${v5meta.permissions.shifts?.write?'true':'false'}" data-roefs-dragstart="event.dataTransfer.setData('text/plain','${s.id}')" data-roefs-click="v5ShiftForm(${s.id})"><b>${esc(s.start_time)}–${esc(s.end_time)}</b><br>${esc(s.employee_name||'Niet toegewezen')}<br>${esc(s.object_name)}<br>${esc(nlDate(s.date))} · ${esc(s.status)}</button>${v5meta.permissions.shifts?.write&&s.status!=='Geannuleerd'?`<button class="btn light v6-resize" data-roefs-click="v6ResizeDialog(${s.id})">↕ Eindtijd aanpassen</button>`:''}`).join('')||'<p>Geen diensten</p>'}</section>`).join('')||'<p>Geen diensten in deze selectie.</p>'}</div><h3>Nog te plannen opdrachten</h3><div class="v5-grid">${v5calendar.unassigned.map(w=>`<article class="v5-item"><b>${esc(w.description)}</b><p>${esc(nlDate(w.date))}</p><button class="btn light" data-roefs-click="v5Work(${w.id})">Opdracht openen</button></article>`).join('')||'<p>Geen open opdrachten.</p>'}</div><h3>Wijzigingsgeschiedenis</h3><div class="v5-history">${v5calendar.history.map(x=>`<p>Dienst #${x.shift_id} · ${esc(x.at)} · versie ${x.after_version} ${v5meta.permissions.shifts?.write&&!x.undone?`<button class="btn light" data-roefs-click="v5Undo(${x.id})">Veilig terugdraaien</button>`:''}</p>`).join('')}</div>`
 }catch(e){toast(e.message)}}
async function v5ShiftForm(id){try{await v5References(['object_id','employee_id','workorder_id']);const row=id?v5calendar.shifts.find(s=>s.id===id):{date:plannerDate,start_time:'08:00',end_time:'12:00',status:'Gepland'};if(!v5meta.permissions.shifts?.write)return toast('Je hebt alleen inzage.');v5Form('Dienst '+(id?'bewerken':'toevoegen'),['object_id','employee_id','date','start_time','end_time','status','workorder_id','planner_notes','break_minutes'],row,`v5ShiftSave(event,${id||0},${row.version||0})`,['object_id','date','start_time','end_time'],['Gepland','Bevestigd','Afgerond','Geannuleerd']);if(id)document.querySelector('#modalbg .actions').insertAdjacentHTML('beforebegin',`<div class="actions"><button type="button" class="btn light" data-roefs-click="v5Resize()">Einde +15 minuten</button>${!row.workorder_id?`<button type="button" class="btn light" data-roefs-click="v5Repeat(${id})">Wekelijks kopiëren</button>`:''}</div>`)}catch(e){toast(e.message)}}
function v5Resize(){const input=$('v5-end_time');let [h,m]=input.value.split(':').map(Number);m+=15;if(m>=60){m-=60;h++}if(h>23)return toast('Kies een geldige eindtijd op dezelfde dag.');input.value=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')}
async function v5ShiftSave(e,id,version){await v5Submit(e,data=>api('v5/shifts'+(id?'/'+id:''),id?'PUT':'POST',{...data,...(id?{version}:{})}))}
async function v5Drop(e,target){e.preventDefault();if(!v5meta.permissions.shifts?.write)return;const id=Number(e.dataTransfer.getData('text/plain'));const row=v5calendar.shifts.find(x=>x.id===id);if(!row||!['date','employee'].includes(v5group))return;const patch=v5group==='date'?{date:target}:{employee_id:target};try{await api('v5/shifts/'+id,'PUT',{...patch,version:row.version});toast('Dienst verplaatst');await v5Calendar()}catch(e){toast(e.message)}}
function v5Repeat(id){showModal('Dienst wekelijks kopiëren',`<p>Alle nieuwe diensten worden samen gecontroleerd en opgeslagen. Bij een conflict wordt niets toegevoegd.</p><form data-roefs-submit="v5RepeatSave(event,${id})"><label>Aantal nieuwe weken<input name="count" type="number" min="1" max="52" value="4" required></label><p id="v5error" class="v5-error" role="alert"></p><button type="submit" class="btn yellow">Kopieën opslaan</button></form>`)}
async function v5RepeatSave(e,id){await v5Submit(e,async data=>{const row=v5calendar.shifts.find(x=>x.id===id),count=Number(data.count),fields=['object_id','employee_id','start_time','end_time','planner_notes'];const base=Object.fromEntries(fields.map(k=>[k,row[k]||'']));await api('v5/planning/bulk','POST',{shifts:Array.from({length:count},(_,i)=>({...base,date:v5DayAdd(row.date,(i+1)*7),status:'Gepland'}))})})}
async function v5Undo(id){try{await api('v5/planning/undo','POST',{history_id:id});await v5Calendar();toast('Wijziging teruggedraaid')}catch(e){toast(e.message)}}
async function v5Notifications(){const [list,pref]=await Promise.all([api('v5/notifications'),api('v5/preferences')]);$('content').innerHTML=head('Mijn meldingen','Interne meldingen voor jouw account. E-mail en push zijn niet geconfigureerd.')+`<label><input type="checkbox" ${pref.notifications?'checked':''} data-roefs-change="v5NotificationPreference(this.checked)"> Nieuwe interne meldingen ontvangen</label><div class="v5-grid">${list.map(n=>`<article class="v5-item"><h3>${esc(n.title)}</h3><p>${esc(n.created_at)} · ${n.read_at?'Gelezen':'Ongelezen'}</p><button class="btn light" data-roefs-click="openPage('${esc(n.target)}')">Open onderdeel</button>${!n.read_at?`<button class="btn yellow" data-roefs-click="v5Read(${n.id})">Markeren als gelezen</button>`:''}</article>`).join('')||'<p>Geen meldingen.</p>'}</div>`}
async function v5NotificationPreference(checked){try{await api('v5/preferences','PUT',{notifications:checked?1:0});toast('Voorkeur opgeslagen')}catch(e){toast(e.message)}}
async function v5Read(id){try{await api('v5/notifications/read','POST',{id});await v5Notifications()}catch(e){toast(e.message)}}
let v5ReportQuery='';
async function v5Reports(){const start=$('v5from')?.value||localDate().slice(0,7)+'-01',end=$('v5to')?.value||localDate(),department=$('reportdept')?.value||'',customer=$('reportcustomer')?.value||'';v5ReportQuery='?from='+start+'&to='+end+'&department='+encodeURIComponent(department)+'&customer_id='+encodeURIComponent(customer);const r=await api('v5/reports'+v5ReportQuery);$('content').innerHTML=head('Rapportages','Berekend uit de actuele opgeslagen gegevens.')+`<div class="v5-toolbar"><label>Van<input id="v5from" type="date" value="${esc(start)}"></label><label>Tot en met<input id="v5to" type="date" value="${esc(end)}"></label><label>Afdeling<input id="reportdept" value="${esc(department)}"></label><label>Klantnummer (intern)<input id="reportcustomer" type="number" value="${esc(customer)}"></label><button class="btn yellow" data-roefs-click="v5Reports()">Rapport tonen</button></div><div class="cards"><button class="card" data-roefs-click="v5Select('calendar')"><b>${r.planned_hours.toLocaleString('nl-NL')}</b><p>Geplande uren</p></button><button class="card" data-roefs-click="v5Select('time')"><b>${Number(r.approved_hours).toLocaleString('nl-NL')}</b><p>Goedgekeurde uren</p></button><button class="card" data-roefs-click="v5Select('workorders')"><b>${r.workorders.length}</b><p>Werkopdrachten</p></button><button class="card" data-roefs-click="v5Select('calendar')"><b>${r.conflicts.length}</b><p>Diensten met conflicten</p></button></div><p>${esc(r.definition)}</p><p>Benutting: ${r.utilization_percent===null?'Niet berekenbaar':r.utilization_percent.toLocaleString('nl-NL')+'%'}</p><button class="btn light" data-roefs-click="v5Download('reports/csv'+v5ReportQuery,'urenrapport.csv')">CSV downloaden</button> <button class="btn light" data-roefs-click="v5Download('reports/pdf'+v5ReportQuery,'rapport.pdf')">PDF downloaden</button><h2>Geregistreerde uren</h2><div class="v5-grid">${r.hours.map(x=>`<article class="v5-item"><b>${esc(x.employee_name)}</b><p>${esc(nlDate(x.date))} · ${esc(x.hours)} uur · ${esc(x.status)}</p>${x.workorder_id?`<button class="btn light" data-roefs-click="v5Work(${x.workorder_id})">Opdracht openen</button>`:''}</article>`).join('')}</div>`}
async function v5Settings(){const [settings,sessions]=await Promise.all([api('v5/settings'),api('v5/sessions')]);$('content').innerHTML=head('Instellingen','Organisatie, planningsgewichten en eigen sessies.')+`<form data-roefs-submit="v5SettingsSave(event)" class="card"><div class="formgrid">${[['organization','Organisatie'],['services','Dienstcategorieën'],['departments','Afdelingen'],['retention_days','Standaard bewaartermijn in dagen']].map(([k,label])=>`<label>${label}<input name="${k}" value="${esc(settings[k]||'')}"></label>`).join('')}${Object.entries(settings.planning_weights||{availability:20,workload:2,familiarity:10,region:10,skills:10}).map(([k,v])=>`<label>Gewicht: ${esc(({availability:'beschikbaarheid',workload:'werkbelasting',familiarity:'locatiekennis',region:'regio',skills:'vaardigheden'})[k])}<input name="weight_${k}" type="number" min="0" max="100" value="${v}"></label>`).join('')}</div><p id="settingerror" class="v5-error" role="alert"></p><button class="btn yellow">Instellingen opslaan</button></form><h2>Herinneringen</h2><p>Maak interne meldingen voor certificaten, contracten en keuringen die binnen 30 dagen verlopen. Opnieuw uitvoeren maakt geen dubbele meldingen voor dezelfde deadline.</p><button class="btn light" data-roefs-click="v5Reminders()">Deadlines controleren</button><h2>Integraties</h2>${Object.values(settings.integrations).map(x=>'<p>'+esc(x)+'</p>').join('')}<h2>Mijn sessies</h2>${sessions.map(s=>`<p>Verloopt ${esc(s.expires)} <button class="btn light" data-roefs-click="v5Revoke('${s.id}')">Sessie intrekken</button></p>`).join('')}`}
async function v5SettingsSave(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),weights={};for(const k of Object.keys(data)){if(k.startsWith('weight_')){weights[k.slice(7)]=Number(data[k]);delete data[k]}else if(!data[k])delete data[k]}data.planning_weights=weights;try{await api('v5/settings','PUT',data);toast('Instellingen opgeslagen')}catch(e){$('settingerror').textContent=e.message}}
async function v5Reminders(){try{await api('v5/reminders/run','POST',{});toast('Deadlinecontrole uitgevoerd; interne meldingen opgeslagen.')}catch(e){toast(e.message)}}
async function v5Revoke(id){try{await api('v5/sessions/revoke','POST',{id});await v5Settings()}catch(e){toast(e.message)}}
// Nieuwe rollen blijven servergestuurd. Rollenlijst wordt uit metadata gelezen.
const oldUsersScreen=usersScreen;
usersScreen=function(){let html=oldUsersScreen();const options=Object.entries(v5meta?.roles||{}).map(([k,v])=>`<option value="${k}" ${k==='employee'?'selected':''}>${esc(v)}</option>`).join('');return html.replace(/<select id="newRole">[\s\S]*?<\/select>/,`<select id="newRole">${options}</select>`)};
const oldEditAccount=editAccount;
editAccount=function(id){oldEditAccount(id);const user=records.find(x=>x.id===id),select=document.querySelector('#modalbg select[name=role]');if(select)select.innerHTML=Object.entries(v5meta.roles).map(([k,v])=>`<option value="${k}" ${k===user.role?'selected':''}>${esc(v)}</option>`).join('')};
async function v5Security(){try{const status=await api('v5/security/mfa/status');showModal('Verificatie in twee stappen',`<p>${status.enabled?'Verificatie is actief. '+status.recovery_remaining+' herstelcodes beschikbaar. Uitschakelen vereist je wachtwoord en een nieuwe code.':'Koppel een authenticator-app. Daarna zijn wachtwoord en actuele code vereist.'}</p><form data-roefs-submit="v5MfaSetup(event,${status.enabled})"><label>Huidig wachtwoord<input name="password" type="password" autocomplete="current-password" required></label>${status.enabled?'<label>Verificatiecode<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label>':''}<p id="v5error" class="v5-error" role="alert"></p><button class="btn yellow">${status.enabled?'Uitschakelen':'Configuratie starten'}</button>${status.enabled?'<button type="button" class="btn light" data-roefs-click="v6RotateRecovery(this.form)">Nieuwe herstelcodes</button>':''}</form>`)}catch(e){toast(e.message)}}
async function v5MfaSetup(e,disable){e.preventDefault();try{const result=await api('v5/security/mfa/'+(disable?'disable':'setup'),'POST',Object.fromEntries(new FormData(e.target)));if(disable){closeModal();token='';loginScreen();return}showModal('Authenticator koppelen',`<p>Bewaar deze sleutel alleen in je eigen authenticator-app:</p><p style="overflow-wrap:anywhere"><b>${esc(result.secret)}</b></p><form data-roefs-submit="v5MfaEnable(event)"><label>Huidig wachtwoord<input name="password" type="password" autocomplete="current-password" required></label><label>Actuele verificatiecode<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><p id="v5error" class="v5-error" role="alert"></p><button class="btn yellow">Activeren en opnieuw inloggen</button></form>`)}catch(e){$('v5error').textContent=e.message}}
async function v5MfaEnable(e){e.preventDefault();try{const result=await api('v5/security/mfa/enable','POST',Object.fromEntries(new FormData(e.target)));v6RecoveryCodes(result.recovery_codes)}catch(e){$('v5error').textContent=e.message}}
const securityShell=shell;shell=function(){securityShell();document.querySelector('.logout')?.insertAdjacentHTML('beforebegin','<button class="btn light" data-roefs-click="v5Security()">Beveiliging</button>')};
boot();

function v6RecoveryCodes(codes){token='';loginScreen();showModal('Bewaar je herstelcodes',`<p>Bewaar deze tien eenmalige codes in je wachtwoordmanager. Ze worden alleen nu getoond. Elke code vervangt één verificatiecode bij inloggen; je wachtwoord blijft nodig.</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${codes.map(esc).join('\n')}</pre><button class="btn yellow" data-roefs-click="closeModal()">Veilig bewaard, naar inloggen</button>`)}

async function v6RotateRecovery(form){try{const result=await api('v5/security/mfa/recovery','POST',Object.fromEntries(new FormData(form)));v6RecoveryCodes(result.recovery_codes)}catch(e){$('v5error').textContent=e.message}}

async function v6Series(){try{const result=await api('v5/planning/series');window.v6series=result.items;showModal('Meerdaagse en terugkerende planning',`<p>Elke dag krijgt een eigen dienst met dezelfde conflictcontrole. Losse segmenten kunnen daarna worden bewerkt. Maximaal 100 segmenten per reeks.</p><button class="btn yellow" data-roefs-click="v6SeriesForm()">Reeks maken</button>${result.items.map(r=>`<article class="v5-item"><b>${esc(r.title)}</b><p>${esc(r.status)} · ${r.items.length} segmenten</p><button class="btn light" data-roefs-click="v6SeriesChange(${r.id},'${r.status==='Actief'?'cancel':'restore'}')">${r.status==='Actief'?'Reeks annuleren':'Veilig herstellen'}</button></article>`).join('')||'<p>Nog geen reeksen.</p>'}`)}catch(e){toast(e.message)}}
async function v6SeriesForm(){await v5References(['object_id','employee_id']);v5Form('Planningsreeks maken',['title','object_id','employee_id','start_date','end_date','start_time','end_time','break_minutes','every_weeks','weekdays','exceptions'],{start_date:plannerDate,end_date:plannerDate,start_time:'08:00',end_time:'12:00',break_minutes:0,every_weeks:1,weekdays:'0,1,2,3,4'},'v6SeriesSave(event)',['title','object_id','start_date','end_date','start_time','end_time']);$('v5-weekdays').insertAdjacentHTML('afterend','<small>0=maandag t/m 6=zondag; komma’s scheiden dagen. Uitzonderingen: datums JJJJ-MM-DD, gescheiden door komma’s.</small>')}
async function v6SeriesSave(e){await v5Submit(e,d=>api('v5/planning/series','POST',{title:d.title,start:d.start_date,end:d.end_date,every_weeks:Number(d.every_weeks),weekdays:d.weekdays.split(',').map(Number),exceptions:d.exceptions.split(',').map(x=>x.trim()).filter(Boolean),template:{object_id:d.object_id,employee_id:d.employee_id,start_time:d.start_time,end_time:d.end_time,break_minutes:Number(d.break_minutes),status:'Gepland'}}))}
async function v6SeriesChange(id,action){const r=v6series.find(x=>x.id===id);v5Form(action==='cancel'?'Reeks annuleren':'Reeks herstellen',['reason'],{},`v6SeriesChangeSave(event,${id},'${action}')`,['reason'])}
async function v6SeriesChangeSave(e,id,action){const r=v6series.find(x=>x.id===id);await v5Submit(e,d=>api('v5/planning/series/'+id,'POST',{action,reason:d.reason,version:r.version,versions:Object.fromEntries(r.items.map(s=>[String(s.id),s.version]))}))}

Object.assign(NL,{title:'Titel',every_weeks:'Herhaal iedere (weken)',weekdays:'Weekdagen',exceptions:'Uitzonderingsdatums',label:'Profielnaam',daily_hours:'Maximum uren per dag',weekly_hours:'Maximum uren per week',minimum_rest_hours:'Minimumrust tussen werkdagen (uren)',break_after_hours:'Pauze verplicht na (uren)',minimum_break_minutes:'Minimale pauze (minuten)'});
const v6OldSettings=v5Settings;
v5Settings=async function(){await v6OldSettings();$('content').insertAdjacentHTML('beforeend','<h2>Arbeidstijdregels</h2><p>Configureer operationele grenzen. Demonstratieregels zijn niet juridisch of aan een cao getoetst.</p><button class="btn light" data-roefs-click="v6Labor()">Regelprofiel bewerken</button><h2>Auditintegriteit</h2><button class="btn light" data-roefs-click="v6Audit()">Controleketen controleren</button>')};
async function v6Labor(){try{const settings=await api('v5/settings'),r=settings.labor_rules||{enabled:false,label:'Fictieve demonstratieregels — juridisch niet gevalideerd',daily_hours:10,weekly_hours:40,minimum_rest_hours:11,break_after_hours:5.5,minimum_break_minutes:30};v5Form('Arbeidstijdregels',['label','daily_hours','weekly_hours','minimum_rest_hours','break_after_hours','minimum_break_minutes'],r,'v6LaborSave(event)',['label']);document.querySelector('#modalbg form').insertAdjacentHTML('afterbegin',`<label><input name="enabled" type="checkbox" ${r.enabled?'checked':''}> Profiel actief afdwingen bij nieuwe of gewijzigde diensten</label><p>Bestaande diensten worden niet stilzwijgend aangepast.</p>`)}catch(e){toast(e.message)}}
async function v6LaborSave(e){await v5Submit(e,d=>api('v5/settings','PUT',{labor_rules:{enabled:!!d.enabled,label:d.label,...Object.fromEntries(['daily_hours','weekly_hours','minimum_rest_hours','break_after_hours','minimum_break_minutes'].map(k=>[k,Number(d[k])]))}}))}
async function v6Audit(){try{const r=await api('v5/security/audit-integrity');showModal('Auditintegriteit',`<p role="status">${r.ok?'Controle geslaagd':'Afwijking gevonden'}: ${r.checked} records gecontroleerd.</p><p>${esc(r.error||r.limitation)}</p>${r.anchor?`<label>Extern te bewaren controleanker<input readonly value="${esc(r.anchor)}"></label>`:''}`)}catch(e){toast(e.message)}}

v5Files=async function(){const [rows,config]=await Promise.all([api('v5/files'),api('v5/files/config')]);v5rows=rows;$('v5body').innerHTML=`<h2>Bestanden</h2><p>Maximaal ${Math.floor(config.max_bytes/1000)} kB. ${esc(config.scanning)} Tekstbijlagen worden als download aangeboden; daarvoor is geen malwarescan bewezen.</p><button class="btn yellow" data-roefs-click="v5Upload()">Bestand uploaden</button><div class="v5-grid">${rows.map(r=>`<article class="v5-item"><h3>${esc(r.name)}</h3><p>${esc(r.category)} · ${esc(r.scan_status)}</p><p>${esc(r.scan_detail)}</p><p>Bewaren tot: ${r.retention_until?esc(nlDate(r.retention_until)):'Geen termijn vastgelegd'}</p><button class="btn light" ${['Schoon','Tekstbijlage'].includes(r.scan_status)?'':'disabled'} data-roefs-click="v5Download('files/${r.id}',${esc(JSON.stringify(r.name))})">Downloaden</button><button class="btn light" data-roefs-click="v6Rescan(${r.id})">Opnieuw scannen</button>${['admin','company_admin'].includes(me.role)?`<button class="btn light" data-roefs-click="v6DeleteFile(${r.id},${r.version})">Verwijderen</button>`:''}</article>`).join('')||'<p>Geen bestanden gevonden.</p>'}</div>`};
async function v6Rescan(id){try{const r=await api('v5/files/'+id+'/rescan','POST',{});toast(r.scan_detail);await v5Files()}catch(e){toast(e.message)}}
function v6DeleteFile(id,version){v5Form('Bestand definitief verwijderen',['reason'],{},`v6DeleteFileSave(event,${id},${version})`,['reason'])}
async function v6DeleteFileSave(e,id,version){await v5Submit(e,d=>api('v5/files/'+id,'DELETE',{reason:d.reason,version}))}

async function v6ClockForm(workorder_id){await v5References(['employee_id']);if(me.role==='employee')v5refs.employees=[{id:me.employee_id,name:me.username}];v5Form('Inklokken',['employee_id'],{employee_id:me.employee_id||''},`v6ClockStart(event,${workorder_id})`,['employee_id'])}
async function v6ClockStart(e,workorder_id){if(await v5Submit(e,d=>api('v5/clock','POST',{workorder_id,employee_id:d.employee_id}))){v5tab='time';await v5Workspace()}}
const v6OldTime=v5Time;
v5Time=async function(){await v6OldTime();const clocks=await api('v5/clock');$('v5body').insertAdjacentHTML('afterbegin',`<h3>Lopende tijdklokken</h3>${clocks.map(c=>`<article class="v5-item"><p>Medewerker #${c.employee_id}, opdracht #${c.workorder_id}<br>Begonnen: ${esc(c.starts_at)}</p><button class="btn yellow" data-roefs-click="v6ClockFinish(${c.id},${c.version},false)">Uitklokken</button><button class="btn light" data-roefs-click="v6ClockFinish(${c.id},${c.version},true)">Klok annuleren</button></article>`).join('')||'<p>Geen lopende tijdklok.</p>'}`)};
function v6ClockFinish(id,version,cancel){v5Form(cancel?'Tijdklok annuleren':'Uitklokken en uren indienen',['break_minutes','reason'],{break_minutes:0},`v6ClockFinishSave(event,${id},${version},${cancel})`,cancel?['reason']:[])}
async function v6ClockFinishSave(e,id,version,cancel){await v5Submit(e,d=>api('v5/clock/'+id,'POST',{...d,version,cancel}))}

const v6SettingsNumbering=v5Settings;
v5Settings=async function(){await v6SettingsNumbering();$('content').insertAdjacentHTML('beforeend','<h2>Conceptnummering</h2><p>Uitsluitend interne conceptnummers; geen definitieve fiscale nummering of verzending.</p><button class="btn light" data-roefs-click="v6Numbering()">Conceptnummerprofiel</button>')};
async function v6Numbering(){try{const s=await api('v5/settings'),r=s.invoice_numbering||{enabled:false,prefix:'ROEFS',width:5};v5Form('Conceptnummering',['prefix','width'],r,'v6NumberingSave(event)',['prefix','width']);document.querySelector('#modalbg form').insertAdjacentHTML('afterbegin',`<label><input name="enabled" type="checkbox" ${r.enabled?'checked':''}> Interne conceptnummerreeks gebruiken</label>`)}catch(e){toast(e.message)}}
async function v6NumberingSave(e){await v5Submit(e,d=>api('v5/settings','PUT',{invoice_numbering:{enabled:!!d.enabled,prefix:d.prefix,width:Number(d.width)}}))}
Object.assign(NL,{prefix:'Voorvoegsel',width:'Aantal cijfers'});

let v6contract=null;
async function v6Contract(id){try{v6contract=await api('v5/contracts/'+id);const c=v6contract.contract,write=v5meta.permissions.contracts?.write;showModal('Contractdossier · '+c.name,`<p>${esc(c.status)} · ${esc(nlDate(c.start_date))} – ${esc(nlDate(c.end_date))}</p><h3>Locaties en frequenties</h3>${v6contract.locations.map(x=>`<p>${esc(x.name)}: ${esc(x.frequency)}</p>`).join('')||'<p>Alleen de oorspronkelijke contractlocatie is gekoppeld.</p>'}${write?`<button class="btn light" data-roefs-click="v6ContractLocations()">Locaties wijzigen</button><h3>Contractbesluit</h3>${(c.status==='Concept'?[['activate','Activeren'],['cancel','Annuleren']]:c.status==='Actief'?[['renew','Verlengen'],['terminate','Beëindigen']]:[]).map(([action,label])=>`<button class="btn light" data-roefs-click="v6ContractDecision('${action}')">${label}</button>`).join('')}`:''}<h3>Gekoppelde opdrachten</h3>${v6contract.workorders.map(w=>`<p>${esc(w.description)} · ${esc(nlDate(w.date))}</p>`).join('')||'<p>Nog geen opdrachten gekoppeld.</p>'}<h3>Besluitgeschiedenis</h3>${v6contract.events.map(x=>`<p>${esc(({renew:'Verlengd',activate:'Geactiveerd',terminate:'Beëindigd',cancel:'Geannuleerd'})[x.action]||x.action)} · ${esc(x.created_at)}<br>${esc(x.reason)}</p>`).join('')||'<p>Nog geen besluiten.</p>'}`)}catch(e){toast(e.message)}}
async function v6ContractLocations(){await v5References(['object_id']);const c=v6contract.contract,choices=v5refs.objects.filter(o=>String(o.customer_id)===String(c.customer_id));showModal('Contractlocaties wijzigen',`<form data-roefs-submit="v6ContractLocationsSave(event)"><p>Kies locaties en leg per locatie de afgesproken frequentie vast.</p>${choices.map(o=>{const linked=v6contract.locations.find(l=>l.object_id===o.id);return `<label><input type="checkbox" name="location" value="${o.id}" ${linked||String(c.object_id)===String(o.id)?'checked':''}> ${esc(o.name)}</label><label>Frequentie voor ${esc(o.name)}<input name="frequency_${o.id}" value="${esc(linked?.frequency||c.frequency||'Volgens afspraak')}" maxlength="100"></label>`}).join('')}<p id="v5error" role="alert"></p><button class="btn yellow" type="submit">Opslaan</button></form>`)}
async function v6ContractLocationsSave(e){e.preventDefault();try{const f=new FormData(e.target),locations=f.getAll('location').map(id=>({object_id:Number(id),frequency:f.get('frequency_'+id)}));await api('v5/contracts/'+v6contract.contract.id+'/locations','PUT',{version:v6contract.contract.version,locations});await v6Contract(v6contract.contract.id)}catch(e){$('v5error').textContent=e.message}}
function v6ContractDecision(action){const c=v6contract.contract;v5Form('Contractbesluit',['reason',...(action==='renew'?['end_date','renewal_date']:[])],{end_date:c.end_date,renewal_date:c.renewal_date},`v6ContractDecisionSave(event,'${action}')`,['reason',...(action==='renew'?['end_date']:[])])}
async function v6ContractDecisionSave(e,action){e.preventDefault();try{await api('v5/contracts/'+v6contract.contract.id+'/decision','POST',{...v5FormData(e.target),action,version:v6contract.contract.version});await v6Contract(v6contract.contract.id)}catch(e){$('v5error').textContent=e.message}}

const v6OldReports=v5Reports;
v5Reports=async function(){await v6OldReports();const r=await api('v5/reports/management'+v5ReportQuery);$('content').insertAdjacentHTML('beforeend',`<h2>Managementoverzichten</h2>${[['employees','Medewerkerbenutting'],['equipment','Materieelbenutting'],['customers','Klantactiviteit'],['contracts','Contractprestaties']].map(([key,label])=>`<section class="card"><h3>${label}</h3>${r.definitions[key]?`<p>${esc(r.definitions[key])}</p>`:''}<button class="btn light" data-roefs-click="v6ManagementDownload('${key}','csv')">CSV downloaden</button><button class="btn light" data-roefs-click="v6ManagementDownload('${key}','pdf')">PDF downloaden</button><div class="v5-grid">${r[key].map(row=>`<article class="v5-item"><b>${esc(row.name)}</b>${Object.entries(row).filter(([k])=>k!=='name').map(([k,v])=>`<p>${esc(v5Label(k))}: ${esc(v===null?'Niet berekenbaar':v)}</p>`).join('')}</article>`).join('')||'<p>Geen gegevens binnen de huidige filters.</p>'}</div></section>`).join('')}${r.finance?`<section class="card"><h3>Financiële voorbereiding</h3><p>${esc(r.definitions.finance)}</p><p>Netto ${esc(nlMoney(r.finance.net))} · Btw ${esc(nlMoney(r.finance.vat))} · Totaal ${esc(nlMoney(r.finance.total))}</p></section>`:''}`)};
async function v6ManagementDownload(section,format){await v5Download('reports/management/'+format+v5ReportQuery+'&section='+section,'management-'+section+'.'+format)}
Object.assign(NL,{planned_hours:'Geplande uren',approved_hours:'Goedgekeurde uren',contract_capacity:'Indicatieve contractcapaciteit',planned_capacity_percent:'Geplande benutting (%)',reserved_hours:'Gereserveerde uren',reservations:'Reserveringen',calendar_utilization_percent:'Kalenderbenutting (%)',workorders:'Werkopdrachten',completed:'Afgeronde opdrachten',asset_id:'Materieelnummer'});

const v6RetentionSettings=v5Settings;
v5Settings=async function(){await v6RetentionSettings();const settings=await api('v5/settings');$('content').insertAdjacentHTML('beforeend',`<h2>Documentretentie</h2><p>Bij inschakelen verwijdert de achtergrondtaak bestanden zodra hun vastgelegde bewaartermijn verstreken is. Auditmetadata blijven behouden. Bestaande backups worden niet verwijderd.</p><label><input type="checkbox" ${settings.document_retention_auto?'checked':''} data-roefs-change="v6RetentionToggle(this.checked)"> Automatische bestandsverwijdering actief</label>`)};
async function v6RetentionToggle(enabled){try{if(enabled&&!confirm('Automatische verwijdering inschakelen? Ook bestaande bestanden met een verstreken bewaartermijn worden definitief uit de actieve opslag verwijderd.'))return v5Settings();await api('v5/settings','PUT',{document_retention_auto:enabled});toast('Bewaarbeleid opgeslagen')}catch(e){toast(e.message);await v5Settings()}}

let v6resizeContext=null;
async function v6ResizeDialog(id){try{const shift=v5calendar.shifts.find(x=>x.id===id);let work=null,shifts=[shift];if(shift.workorder_id){const r=await api('v5/workorders/'+shift.workorder_id);work=r.workorder;shifts=r.shifts.filter(x=>x.status!=='Geannuleerd')}v6resizeContext={shift,work,shifts};const minutes=t=>Number(t.slice(0,2))*60+Number(t.slice(3));showModal('Eindtijd visueel aanpassen',`<form data-roefs-submit="v6ResizeSave(event)"><p>${work?'Wijzigt het tijdvak van de opdracht en alle '+shifts.length+' actieve teamdiensten in één transactie.':'Wijzigt deze dienst.'} Conflicten worden vóór opslaan gecontroleerd.</p><label>Eindtijd: <output id="v6resizeTime">${esc(shift.end_time)}</output><input name="minutes" type="range" min="${minutes(shift.start_time)+1}" max="1439" step="1" value="${minutes(shift.end_time)}" aria-label="Eindtijd in minuten na middernacht" data-roefs-input="v6ResizePreview(this.value)"></label><p>Gebruik de schuif, pijltjestoetsen of het gewone dienstformulier.</p><p id="v5error" role="alert"></p><button type="submit" class="btn yellow">Tijdvak opslaan</button></form>`)}catch(e){toast(e.message)}}
function v6MinuteTime(value){const n=Number(value);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function v6ResizePreview(value){$('v6resizeTime').textContent=v6MinuteTime(value)}
async function v6ResizeSave(e){await v5Submit(e,d=>api('v5/planning/resize/'+v6resizeContext.shift.id,'POST',{version:v6resizeContext.shift.version,end_time:v6MinuteTime(d.minutes),work_version:v6resizeContext.work?.version,versions:Object.fromEntries(v6resizeContext.shifts.map(x=>[String(x.id),x.version]))}))}
